<?php declare(strict_types=1); namespace App\Domain\Academics\Actions; use App\Domain\Academics\Models\AcademicYear; use App\Domain\Academics\Models\Enrollment; use App\Domain\Academics\Models\Section; use App\Domain\People\Models\Student; use App\Domain\Schools\Models\School; use Exception; use Illuminate\Support\Facades\DB; class EnrollStudent { public function __construct(private readonly School $school) {} public function execute(array $data): Enrollment { if (empty($data["student_id"]) || empty($data["section_id"]) || empty($data["academic_year_id"])) { throw new Exception("Student, section, and academic year are required."); } $student = Student::find($data["student_id"]); if (! $student || $student->school_id !== $this->school->id) { throw new Exception("Student not found for this school."); } $section = Section::find($data["section_id"]); if (! $section || $section->school_id !== $this->school->id) { throw new Exception("Section not found for this school."); } $academicYear = AcademicYear::find($data["academic_year_id"]); if (! $academicYear || $academicYear->school_id !== $this->school->id) { throw new Exception("Academic year not found for this school."); } $existingEnrollment = Enrollment::where("student_id", $student->id)->where("academic_year_id", $academicYear->id)->whereNull("withdrawal_date")->first(); if ($existingEnrollment) { throw new Exception("Student is already actively enrolled in this academic year."); } if ($section->current_count >= $section->capacity) { throw new Exception("Section has reached its maximum capacity."); } $data["school_id"] = $this->school->id; $data["enrollment_date"] ??= now()->toDateString(); $data["status"] ??= "active"; return DB::transaction(function () use ($data, $section) { $enrollment = Enrollment::create($data); $section->increment("current_count"); return $enrollment; }); } }
